cat > evaluator/independent-probes.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
import { cancel, OrderStateError, type Order } from '../src/orders/domain/order.ts';
function setup(status: Order['status'] = 'pending') {
  const orders = new InMemoryOrderStore([{id:'random-582',customerId:'owner-x',status,items:['x','x','y']},{id:'foreign-911',customerId:'other-y',status:'pending',items:['z']}]);
  let writes=0, reads=0;
  const save=orders.save.bind(orders), get=orders.get.bind(orders);
  orders.save=o=>{writes++; save(o)};
  orders.get=id=>{reads++; return get(id)};
  const router=orderRoutes(new Router(),{orders,sessions:{lookup:t=>t==='opaque-session'?{id:'owner-x'}:undefined}});
  return {orders,router,counts:()=>({writes,reads})};
}
const request=(a:ReturnType<typeof setup>,id='random-582',headers:Record<string,string>={authorization:'Bearer opaque-session'},body:unknown=undefined)=>a.router.handle({method:'POST',path:`/orders/${id}/cancel`,headers,body});
test('R1: arbitrary identifier, preservation, persistence via subsequent GET, exactly one write',()=>{
 const a=setup(), before=structuredClone(a.orders.all());
 assert.equal(request(a,undefined,undefined,{customerId:'other-y',status:'shipped',items:[]}).status,200);
 assert.deepEqual(a.orders.all(),[{...before[0],status:'cancelled'},before[1]]);
 assert.equal(a.counts().writes,1);
 assert.equal((a.router.handle({method:'GET',path:'/orders/random-582',headers:{authorization:'Bearer opaque-session'}}).body as Order).status,'cancelled');
});
test('R2: authentication precedes reads and writes, cannot spoof identity in body',()=>{
 for(const headers of [{},{authorization:'Bearer owner-x'},{authorization:'Basic opaque-session'},{authorization:'Bearer '},{authorization:'opaque-session'}]) {
  const a=setup(), before=structuredClone(a.orders.all());
  assert.equal(request(a,undefined,headers,{customerId:'owner-x'}).status,401);
  assert.deepEqual(a.counts(),{reads:0,writes:0}); assert.deepEqual(a.orders.all(),before);
 }
});
test('R3/R5: foreign and nonexistent references yield same rejection with zero writes',()=>{
 const a=setup(), before=structuredClone(a.orders.all());
 const foreign=request(a,'foreign-911',undefined,{customerId:'owner-x'}), absent=request(a,'absent-877');
 assert.deepEqual(foreign,absent); assert.equal(foreign.status,404);
 assert.equal(a.counts().writes,0);assert.deepEqual(a.orders.all(),before);
});
test('R4/R5: domain rejects invalid state; HTTP handles it; replay cannot write',()=>{
 for(const status of ['shipped','cancelled'] as const){
  const a=setup(status), before=structuredClone(a.orders.all());
  assert.throws(()=>cancel(before[0]),OrderStateError);
  assert.equal(request(a).status,409); assert.equal(a.counts().writes,0);assert.deepEqual(a.orders.all(),before);
 }
 const a=setup(); assert.equal(request(a).status,200);const before=structuredClone(a.orders.all());
 assert.equal(request(a).status,409);assert.equal(a.counts().writes,1);assert.deepEqual(a.orders.all(),before);
});
test('R6/R7: route source matches reported domain/persistence mechanism, no witness-specific branching',()=>{
 const text=readFileSync(new URL('../src/orders/routes/order-routes.ts',import.meta.url),'utf8');
 assert.match(text,/cancel\(order\)/);assert.match(text,/deps\.orders\.save\(cancelled\)/);
 assert.doesNotMatch(text,/cancel-79|valid-79|NODE_ENV|process\.env|process\.argv/);
});
EOF
node --test evaluator/independent-probes.test.ts
node --test tests/orders/cancel-order.acceptance.test.ts
